"""Pinned projection regressions, not survey-control or province-boundary evidence."""
from copy import deepcopy

import pytest

from wn_import.models import ReviewConfig
from test_engine import block_feature, config, feature, run
from test_georeference import controls


# Explicit VN-2000 EPSG definitions, projected metre input. Expected WGS84 outputs
# are frozen from PROJ's supported non-ballpark operation, not reverse-generated by
# the tested engine. These numerical checks do not assert cadastral survey accuracy.
VN2000_CASES = [
    (9209, [[105.50188313213067, 21.000421880317624],
            [105.50284504735403, 21.00042186687921]]),
    (9210, [[105.75188255284358, 21.00041909439462],
            [105.75284446792908, 21.00041908095942]]),
    (3405, [[105.00188426286215, 21.006725053994412],
            [105.00284650742182, 21.006725040540964]]),
    (3406, [[111.00186221557883, 21.006658451038813],
            [111.00282445684313, 21.006658437708907]]),
]


@pytest.mark.parametrize('code,expected', VN2000_CASES)
@pytest.mark.parametrize('axis,units', [('xy', 'm'), ('yx', 'm'), ('xy', 'mm'), ('yx', 'mm')])
def test_explicit_vn2000_projection_axis_and_units_with_original_raw_preserved(code, expected, axis, units):
    source = [[500000, 2323000], [500100, 2323000]]
    if axis == 'yx':
        source = [point[::-1] for point in source]
    if units == 'mm':
        source = [[value * 1000 for value in point] for point in source]
    raw = [feature('pipe', source)]
    original = deepcopy(raw)
    result = run(raw, sourceCrs=f'EPSG:{code}', sourceAxisOrder=axis,
                 sourceUnits=units, sourceCrsPresetId=f'vn2000-{code}')
    assert result['state'] == 'ready', result['issues']
    assert result['coordinateSpace'] == 'EPSG:4326'
    pipe = next(f for f in result['clean'] if f['properties'].get('kind') == 'Pipe')
    for actual, known in zip(pipe['geometry']['coordinates'], expected):
        assert actual == pytest.approx(known, abs=1e-8)
    assert 99 < result['summary']['totalLengthM'] < 101
    assert result['raw'][0]['geometry']['coordinates'] == original[0]['geometry']['coordinates']
    assert raw == original


def test_axis_and_scale_apply_to_explicit_node_and_file_crs_override():
    raw = [feature('pipe', [[2323000000, 500000000], [2323000000, 500100000]]),
           block_feature('node', [2323000000, 500000000], 'Junction')]
    original = deepcopy(raw)
    result = run(raw, sourceCrs=None, fileCrs=[{'fileId': 'file1', 'sourceCrs': 'EPSG:9209'}],
                 sourceAxisOrder='yx', sourceUnits='mm', blockRules=[{
                     'fileId': 'file1', 'blockName': 'Junction', 'action': 'node', 'nodeType': 'Junction'}])
    assert result['state'] == 'ready', result['issues']
    node = next(f for f in result['clean'] if f['id'] == 'node')
    assert node['geometry']['coordinates'] == pytest.approx(VN2000_CASES[0][1][0], abs=1e-8)
    assert raw == original
    assert result['raw'][1]['geometry']['coordinates'] == original[1]['geometry']['coordinates']


@pytest.mark.parametrize('source_crs', ['EPSG:4326', 'EPSG:4978', 'EPSG:2263'])
def test_mm_requires_projected_crs_with_metre_axes(source_crs):
    result = run([feature('pipe', [[500000000, 2323000000], [500100000, 2323000000]])],
                 sourceCrs=source_crs, sourceUnits='mm')
    assert result['state'] == 'needs_review' and not result['drafts']
    assert result['coordinateSpace'] == 'cad'
    assert any(i['code'] == 'SOURCE_UNITS_REQUIRE_METRIC_CRS' for i in result['issues'])


def test_mm_validation_checks_effective_per_file_crs():
    result = run([feature('pipe', [[500000000, 2323000000], [500100000, 2323000000]])],
                 sourceCrs='EPSG:9209', sourceUnits='mm',
                 fileCrs=[{'fileId': 'file1', 'sourceCrs': 'EPSG:4326'}])
    assert not result['drafts']
    assert any(i['code'] == 'SOURCE_UNITS_REQUIRE_METRIC_CRS' for i in result['issues'])


@pytest.mark.parametrize('overrides', [
    {'sourceCrs': 'EPSG:9209'},
    {'sourceCrs': None, 'fileCrs': [{'fileId': 'file1', 'sourceCrs': 'EPSG:9210'}]},
])
def test_direct_crs_without_evidence_has_geographic_overlay_but_no_asset_drafts(overrides):
    result = run([feature('pipe', [[500000, 2323000], [500100, 2323000]])],
                 crsEvidence=' \n ', **overrides)
    assert result['coordinateSpace'] == 'EPSG:4326' and result['clean']
    assert result['state'] == 'needs_review' and not result['drafts']
    assert any(i['code'] == 'CRS_EVIDENCE_REQUIRED' for i in result['issues'])


@pytest.mark.parametrize('option', [{'sourceAxisOrder': 'yx'}, {'sourceUnits': 'mm'}])
@pytest.mark.parametrize('mode', [
    {'controlPoints': [{'source': [0, 0], 'target': None}]},
    {'controlPointTargetCrs': 'EPSG:4326'},
    {'controlPoints': controls(), 'controlPointTargetCrs': 'EPSG:4326'},
])
def test_direct_source_options_cannot_silently_change_control_point_inputs(option, mode):
    with pytest.raises(ValueError, match='sourceAxisOrder=xy'):
        ReviewConfig(expectedVersion=1, **option, **mode)


def test_preset_is_metadata_and_cannot_supply_crs_or_evidence():
    result = run([feature('pipe', [[500000, 2323000], [500100, 2323000]])],
                 sourceCrs=None, sourceCrsPresetId='vn2000-9209')
    assert result['coordinateSpace'] == 'cad' and not result['drafts']
    assert any(i['code'] == 'CRS_REQUIRED' for i in result['issues'])
    assert config().sourceAxisOrder == 'xy' and config().sourceUnits == 'm'
    assert config().sourceCrsPresetId is None
    with pytest.raises(ValueError):
        config(sourceCrsPresetId='x' * 121)
    with pytest.raises(ValueError):
        config(sourceUnits='ft')
    with pytest.raises(ValueError):
        config(sourceAxisOrder='auto')


def test_unavailable_datum_operation_never_falls_back_to_ballpark():
    result = run([feature('pipe', [[500000, 2323000], [500100, 2323000]])],
                 sourceCrs='+proj=tmerc +lat_0=0 +lon_0=105.5 +k=0.9999 '
                           '+x_0=500000 +y_0=0 +ellps=clrk66 +units=m +no_defs')
    assert result['state'] == 'needs_review' and not result['drafts']
    assert any(i['code'] == 'INVALID_CRS' for i in result['issues'])
